/* ---------- index TF-IDF (fallback si pas d'embeddings) ---------- */
let DF = {}, N = 0;
function buildIndex(){
  DATA.forEach(r=> r._tok = toks((r.title||"")+" "+(r.sector||"")));
  DF = {}; DATA.forEach(r=> new Set(r._tok).forEach(t=> DF[t]=(DF[t]||0)+1));
  N = DATA.length;
}
const idf = t => Math.log(1 + N/((DF[t]||0)+1));

/* ---------- moteur TF-IDF ---------- */
function analyse(query){
  const qt = toks(query);
  if(!qt.length) return null;
  const sectorScore = {};
  for(const t of qt){ if(ALIAS[t]) sectorScore[ALIAS[t]] = (sectorScore[ALIAS[t]]||0)+2; }
  for(const [sec,kws] of Object.entries(SECTORS)){
    let hit=0;
    for(const t of qt){ if(kws.includes(t)) hit++; }
    if(hit) sectorScore[sec]=(sectorScore[sec]||0)+hit;
  }
  const intended = Object.keys(sectorScore).sort((a,b)=>sectorScore[b]-sectorScore[a]);
  const qbag = {};
  qt.forEach(t=> qbag[t]=Math.max(qbag[t]||0,1));
  intended.slice(0,2).forEach(sec=> SECTORS[sec].forEach(k=>{ qbag[k]=Math.max(qbag[k]||0,0.4); }));
  return {qt, intended, qbag, sectorSet:new Set(intended)};
}

function cosineTFIDF(qbag, rtok){
  const rtf = {}; rtok.forEach(t=> rtf[t]=(rtf[t]||0)+1);
  let dot=0,nq=0,nr=0;
  for(const [t,w] of Object.entries(qbag)){ const i=idf(t); nq += (w*i)**2; if(rtf[t]) dot += (w*i)*(rtf[t]*i); }
  for(const [t,f] of Object.entries(rtf)){ const i=idf(t); nr += (f*i)**2; }
  return (nq&&nr) ? dot/Math.sqrt(nq*nr) : 0;
}

