function scoreColor(s){
  if(s>=80) return "var(--blue-lighter)";
  if(s>=60) return "var(--blue-lighter)"; /* dupliquait déjà --om-blue-lighter en dur (#60A5FA) avant l'alignement DA */
  if(s>=40) return "#8295B5";
  return "#54678A";
}
function esc(s){return (s||"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}

/* ---------- fraîcheur ----------
   first_seen = date à laquelle le scraper a détecté l'épisode pour la première
   fois (écrit par scrape_openmedias.py). Les entrées antérieures à la mise en
   place du suivi portent "legacy" et ne sont jamais comptées comme nouvelles. */
const NEW_DAYS = 7;
function daysSince(iso){
  if(!iso || iso === "legacy") return Infinity;
  const t = Date.parse(iso + "T00:00:00");
  if(isNaN(t)) return Infinity;
  return Math.floor((Date.now() - t) / 86400000);
}
function isNew(r){ return daysSince(r.first_seen) <= NEW_DAYS; }
function lastUpdate(){
  const dates = DATA.map(r=>r.first_seen).filter(d=>d && d !== "legacy").sort();
  return dates.length ? dates[dates.length-1] : null;
}
function frDate(iso){
  const t = Date.parse(iso + "T00:00:00");
  return isNaN(t) ? iso : new Date(t).toLocaleDateString("fr-FR",
    {weekday:"long", day:"numeric", month:"long"});
}

function cardNous({r,score,kw,sectorMatch}){
  const thumb = r.thumb
    ? `<img loading="lazy" src="${esc(r.thumb)}" alt="" onerror="this.parentNode.innerHTML='<div class=ph>'+${JSON.stringify(esc('OpenMedias'))}+'</div>'">`
    : `<div class="ph">${esc(r.media)}</div>`;
  const scoreHtml = score==null ? "" :
    `<div class="score" style="color:${scoreColor(score)}"><b>${score}</b><span>/100</span></div>`;
  let why="";
  if(score!=null){
    const parts=[];
    if(sectorMatch) parts.push(`<span class="hit">Secteur ${esc(r.sector)} ✓</span>`);
    if(kw&&kw.length) parts.push("Termes : "+kw.map(k=>`<span class="kw">${esc(k)}</span>`).join(", "));
    if(parts.length) why=`<div class="why">${parts.join(" · ")}</div>`;
  }
  const date = r.date?` · ${esc(r.date)}`:"";
  const newTag = isNew(r) ? `<span class="tag tag-new">Nouveau</span>` : "";
  return `<article class="card card-nous">
    <div class="top">${thumb}
      <div class="ribbon">${newTag}<span class="tag tag-nous">OpenMedias</span><span class="tag tag-media">${esc(r.media)}</span></div>
      ${scoreHtml}
    </div>
    <div class="body">
      <div class="sub">${esc(r.emission)}${date}</div>
      <h3>${esc(r.title)}</h3>
      <span class="sector-tag">${esc(r.sector)}</span>
      ${why}
      <span class="open-lbl">Voir l'émission →</span>
    </div>
    <a class="open" href="${esc(r.url)}" target="_blank" rel="noopener" aria-label="${esc(r.title)}"></a>
  </article>`;
}

function miniConcu({r,score,kw,sectorMatch}){
  const scoreHtml = score!=null ? `<div class="m-score">${score}/100</div>` : "";
  let why="";
  if(score!=null && kw && kw.length){
    why=`<div class="m-why">Termes : `+kw.map(k=>`<span class="kw">${esc(k)}</span>`).join(", ")+"</div>";
  }
  const date = r.date ? ` · ${esc(r.date.slice(0,7))}` : "";
  const newTag = isNew(r) ? `<span class="m-new">Nouveau</span>` : "";
  return `<article class="mini">
    <div class="m-title">${newTag}${esc(r.title)}</div>
    <div class="m-sub">${esc(r.media)} · ${esc(r.emission)}${date}</div>
    ${scoreHtml}${why}
    <a class="open" href="${esc(r.url)}" target="_blank" rel="noopener" aria-label="${esc(r.title)}"></a>
  </article>`;
}

