function buildAngleBox(q, sector){
  const angles = (sector && ANGLE_TEMPLATES[sector]) ? ANGLE_TEMPLATES[sector] : ANGLE_DEFAULT;
  const items = angles.map(a=>`<div class="angle-item"><b>💡 ${esc(a.titre)}</b>${esc(a.desc)}</div>`).join("");
  return `<div class="angle-box">
    <div class="angle-title">🎯 Aucune émission trouvée sur « ${esc(q)} » — Angles à proposer à l'édito :</div>
    <div class="angle-list">${items}</div>
  </div>`;
}

async function run(){
  const q = state.q.trim();
  let pool = await search(q, state.src);
  if(state.sector) pool = pool.filter(o=>o.r.sector===state.sector);
  let nous  = pool.filter(o=>o.r.source==="Nous");
  let concu = pool.filter(o=>o.r.source==="Concurrents");
  // Filtre média uniquement sur nos émissions (la concu reste complète)
  if(state.media) nous = nous.filter(o=>o.r.media===state.media);
  // Filtre période
  if(state.period){
    const now=new Date(); const cutoff=new Date(now);
    if(state.period==='3m') cutoff.setMonth(now.getMonth()-3);
    else if(state.period==='6m') cutoff.setMonth(now.getMonth()-6);
    else if(state.period==='1y') cutoff.setFullYear(now.getFullYear()-1);
    const filterDate=o=>{if(!o.r.date)return true; return new Date(o.r.date)>=cutoff;};
    nous=nous.filter(filterDate); concu=concu.filter(filterDate);
  }

  // bandeau
  if(q){
    bandeauEl.classList.add("show");
    const n=nous.length, c=concu.length, tot=n+c||1;
    bandeauTxt.innerHTML = `Sur « <b>${esc(scanLabel||q)}</b> » : <b style="color:var(--nous)">${n}</b> chez nous · <b style="color:var(--concu)">${c}</b> chez les concurrents`;
    barNous.style.width = (n/tot*100)+'%';
    barConcu.style.width = (c/tot*100)+'%';
    bandeauNote.textContent = n===0 ? "Angle à proposer à l'édito ?" : n>=5 ? "Bonne couverture ✓" : "Couverture partielle";
  } else {
    bandeauEl.classList.remove("show");
  }

  // nos émissions
  countNousEl.textContent = nous.length ? `${nous.length} résultat${nous.length>1?"s":""}` : "";
  gridNous.innerHTML = nous.length
    ? nous.map(cardNous).join("")
    : (q ? buildAngleBox(q, state.sector) : `<div class="empty"><b>Importez votre catalogue</b>Bouton « Importer catalogue » en haut → sélectionnez le catalogue.json généré par le scraper.</div>`);

  // concurrents
  countConcuEl.textContent = concu.length ? `${concu.length} résultat${concu.length>1?"s":""}` : "";
  gridConcu.innerHTML = concu.length
    ? concu.slice(0,30).map(miniConcu).join("") + (concu.length>30?`<div class="empty-mini"><b>+${concu.length-30} autres</b>Affinez la recherche pour les voir.</div>`:"")
    : `<div class="empty-mini"><b>${q?"Aucun concurrent trouvé":"Veille concurrents"}</b>${q?"":"Les émissions concurrentes apparaissent ici."}</div>`;
}

