function isURL(s){ try{ const u=new URL(s.trim()); return u.protocol.startsWith("http"); }catch(_){return false;} }

// `deny` : tokens à ignorer (ex. nom de l'entreprise scannée). `squash` : le
// hostname écrasé ("beoffframecom") — un mot-clé qui y est CONTENU est un
// morceau du nom de marque ("frame" ⊂ "beoffframe") et pollue le matching.
// Ponctuation strippée (norm seul gardait "frame:" et "frame," comme deux
// mots distincts) et tokens avec chiffres exclus ("2023" n'est pas un mot-clé).
function extractKeywords(text, deny = new Set(), squash = ""){
  const words = norm(text).replace(/[^a-z0-9 ]/g," ").split(/\s+/)
    .filter(w => w.length>3 && !STOP.has(w) && !/\d/.test(w) && !deny.has(w) && !(squash && squash.includes(w)));
  const freq = {};
  words.forEach(w=>freq[w]=(freq[w]||0)+1);
  return Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,12).map(e=>e[0]);
}

let scanLabel = null; // label affiché dans le bandeau après scan URL
// Texte COMPLET du site prospect après analyse d'URL : c'est lui qu'on envoie
// à l'encodeur sémantique (bien plus riche que les 8 mots-clés affichés dans
// la barre de recherche — la fréquence brute des mots d'une homepage donne un
// mauvais signal, le vecteur du texte entier capture le métier réel).
// Remis à null dès que l'utilisateur tape une requête à la main.
let semanticOverride = null;

async function fetchPageText(url){
  const hostname = new URL(url).hostname.replace(/^www\./, "");
  const company  = hostname.split(".")[0];

  // 0. NOTRE serveur (route /radar/api/page-text, ajoutée après fusion) —
  // fiable, vrai User-Agent navigateur, pas de proxy tiers. Remplace les
  // sources 1-3 ci-dessous, gardées en secours seulement.
  try {
    const r = await fetch("api/page-text?url=" + encodeURIComponent(url), {signal: AbortSignal.timeout(12000)});
    if(r.ok){
      const d = await r.json();
      if(d.text && d.text.length > 80) return {text: d.text, title: d.title || "", source: "server"};
    }
  } catch(_){}

  // 1. DuckDuckGo — meilleur pour grands comptes, retourne un résumé métier propre
  try {
    const ddgRes = await fetch(
      "https://api.duckduckgo.com/?q=" + encodeURIComponent(company) +
      "&format=json&no_html=1&skip_disambig=1",
      {signal: AbortSignal.timeout(8000)}
    );
    if(ddgRes.ok){
      const ddg = await ddgRes.json();
      const abstract = ddg.AbstractText || "";
      const topics   = (ddg.RelatedTopics||[]).slice(0,5).map(t=>t.Text||"").join(" ");
      const combined = [abstract, topics].join(" ").trim();
      if(combined.length > 80){
        return {text: combined, title: ddg.Heading || company, source:"ddg"};
      }
    }
  } catch(_){}

  // 2. allorigins — fetche le HTML, utile pour PME avec site accessible
  try {
    const proxy = "https://api.allorigins.win/get?url=" + encodeURIComponent(url);
    const res   = await fetch(proxy, {signal: AbortSignal.timeout(8000)});
    const {contents} = await res.json();
    if(contents && contents.length > 200){
      const doc = new DOMParser().parseFromString(contents, "text/html");
      // Supprimer scripts, styles, nav, footer, cookie banners
      doc.querySelectorAll("script,style,nav,footer,header,[class*=cookie],[class*=consent],[id*=cookie],[id*=consent],[class*=gdpr],[class*=rgpd],[class*=banner],[class*=popup],[class*=modal]").forEach(e=>e.remove());
      const t = doc.querySelector("title")?.textContent || "";
      const d = doc.querySelector('meta[name="description"]')?.getAttribute("content") || "";
      const h = [...doc.querySelectorAll("h1,h2,h3")].map(e=>e.textContent).join(" ");
      const p = [...doc.querySelectorAll("p,li")].slice(0,15).map(e=>e.textContent).join(" ");
      const text = [t,d,h,p].join(" ").replace(/<[^>]+>/g,"");
      if(text.trim().length > 100) return {text, title:t, source:"allorigins"};
    }
  } catch(_){}

  // 3. Microlink — titre + description uniquement (évite les banners)
  try {
    const mlRes = await fetch("https://api.microlink.io?url=" + encodeURIComponent(url), {
      signal: AbortSignal.timeout(8000)
    });
    if(mlRes.ok){
      const {data} = await mlRes.json();
      const title = data?.title || "";
      const desc  = data?.description || "";
      if(desc && desc.length > 40){
        return {text:[title, desc].join(" "), title, source:"microlink"};
      }
    }
  } catch(_){}

  // 4. Dernier recours — domaine seul
  return {text: hostname + " " + company, title: company, source:"domain"};
}

async function scanURL(url){
  scanBtn.disabled = true;
  scanBtn.textContent = "Analyse…";
  scanTxt.innerHTML = `<b>Analyse en cours…</b> Lecture du site prospect`;
  scanKwRow.style.display = "none";

  const result = await fetchPageText(url);

  // result est toujours défini (fallback domaine en dernier recours)
  if(!result || !result.text || result.text.trim().length < 5){
    scanTxt.innerHTML = `<b>Impossible d'analyser ce site</b> — Colle une description de l'activité.`;
    scanBtn.disabled = false;
    scanBtn.textContent = "Réessayer";
    return;
  }

  const raw = result.text.replace(/<[^>]+>/g,"").slice(0,6000);
  // Titre lisible (déclaré AVANT hostTokens — une utilisation avant la
  // déclaration du `const` jetait une ReferenceError et l'analyse restait
  // bloquée sur "Analyse en cours…", bouton désactivé).
  const hostname = new URL(url).hostname.replace("www.","");
  const displayTitle = result.title || hostname;
  // Tokens du nom de domaine exclus des mots-clés (le nom de l'entreprise
  // pollue le matching, il est déjà dans le titre affiché).
  const hostTokens = new Set(norm(hostname).replace(/[^a-z0-9 ]/g," ").split(/\s+/).filter(w=>w.length>2));
  const hostSquash = norm(hostname).replace(/[^a-z0-9]/g,"");
  const kws = extractKeywords(raw, hostTokens, hostSquash);
  const query = kws.slice(0,8).join(" ");
  semanticOverride = raw.slice(0,2000); // pour l'encodeur sémantique (voir searchSemantic)

  // Afficher mots-clés
  const srcLabel = result.source==='server'?' (analysé par notre serveur)':result.source==='ddg'?' (via DuckDuckGo)':result.source==='microlink'?' (via métadonnées)':result.source==='domain'?' (domaine uniquement — ajoute une description si besoin)':'';
  scanTxt.innerHTML = `<b>${esc(displayTitle.slice(0,60))}</b>${srcLabel} — Mots-clés identifiés :`;
  scanKwRow.innerHTML = kws.slice(0,12).map(k=>`<span class="scan-kw">${esc(k)}</span>`).join("");
  scanKwRow.style.display = "flex";

  // Auto-détecter secteur
  const detectedSector = detectSectorFromTokens(kws);
  if(detectedSector){
    state.sector = detectedSector;
    [...document.getElementById("chips").children].forEach(x=>
      x.classList.toggle("on", x.dataset.sec===detectedSector)
    );
  }

  // Lancer la recherche
  scanLabel = displayTitle.slice(0,50) || hostname;
  qEl.value = query;
  state.q = query;
  run();

  scanBtn.disabled = false;
  scanBtn.textContent = "Analyser →";
}


// Match EXACT uniquement (le double substring t.includes(k)||k.includes(t)
// faisait matcher "agence" sur le mot-clé "agence immobiliere" → une agence de
// communication se voyait filtrer le secteur Immobilier, qui écrasait tous les
// résultats). Seuil 2 : un seul mot générique ne doit pas imposer un secteur.
function detectSectorFromTokens(tokens){
  let best=null, bestScore=0;
  for(const [sec, kws] of Object.entries(SECTORS)){
    const score = tokens.filter(t=> kws.includes(t)).length;
    if(score>bestScore){bestScore=score; best=sec;}
  }
  return bestScore>=2 ? best : null;
}

scanBtn.addEventListener("click", ()=>{
  const url = qEl.value.trim();
  if(isURL(url)) scanURL(url);
});

let t; qEl.addEventListener("input",()=>{
  const v=qEl.value;
  state.q=v; scanLabel=null; semanticOverride=null;
  qEl.style.height="auto"; qEl.style.height=Math.min(200,qEl.scrollHeight)+"px";
  // Affiche la barre URL si c'est une URL
  if(isURL(v.trim())){
    urlScanBar.classList.add("show");
    scanTxt.innerHTML=`<b>URL détectée</b> — Analyser ce site pour trouver les émissions qui matchent ?`;
    scanKwRow.style.display="none";
    scanBtn.textContent="Analyser →";
    scanBtn.disabled=false;
    return; // pas de recherche TF-IDF sur une URL brute
  } else {
    urlScanBar.classList.remove("show");
  }
  // Auto-détecter et appliquer secteur depuis la requête
  if(v.trim().length >= 4 && !isURL(v.trim())){
    const detected = detectSectorFromQuery(v);
    if(detected && detected !== state.sector) applySectorChip(detected);
    else if(!detected && state.sector && state._autoSector) applySectorChip(null);
    state._autoSector = !!detected;
  }
  clearTimeout(t); t=setTimeout(run,120);
});
document.getElementById("src").addEventListener("click",e=>{
  const b=e.target.closest("button"); if(!b)return;
  state.src=b.dataset.src;
  [...e.currentTarget.children].forEach(x=>x.setAttribute("aria-pressed",x===b));
  run();
});

