/* ── STATS D'USAGE ── */
const STATS_KEY = "radar_stats_v1";

function loadStats(){
  try{ return JSON.parse(localStorage.getItem(STATS_KEY)||"[]"); }
  catch(_){ return []; }
}
function saveStats(entries){ localStorage.setItem(STATS_KEY, JSON.stringify(entries.slice(-500))); }

function trackSearch(q, sector, media){
  if(!q || q.length < 2) return;
  const entries = loadStats();
  entries.push({q, sector:sector||null, media:media||null, ts: Date.now()});
  saveStats(entries);
}

function renderStats(){
  const entries = loadStats();
  const today = new Date(); today.setHours(0,0,0,0);
  const todayEntries = entries.filter(e=>e.ts>=today.getTime());

  // KPIs
  const freq = {};
  entries.forEach(e=>freq[e.q]=(freq[e.q]||0)+1);
  document.getElementById("stats-grid").innerHTML = `
    <div class="stat-box"><div class="stat-n">${entries.length}</div><div class="stat-lbl">Recherches totales</div></div>
    <div class="stat-box"><div class="stat-n">${todayEntries.length}</div><div class="stat-lbl">Aujourd'hui</div></div>
    <div class="stat-box"><div class="stat-n">${Object.keys(freq).length}</div><div class="stat-lbl">Requêtes uniques</div></div>
  `;
  const oldest = entries[0]?.ts;
  document.getElementById("stats-sub").textContent = oldest
    ? `Depuis le ${new Date(oldest).toLocaleDateString("fr-FR")} — ${entries.length} événements enregistrés`
    : "Aucune donnée encore — lance des recherches !";

  // Top recherches
  const topQ = Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const maxQ = topQ[0]?.[1]||1;
  document.getElementById("stats-searches").innerHTML = topQ.map(([q,n])=>
    `<div class="stats-row"><span class="sr-label">${esc(q.slice(0,40))}</span>
    <div class="sr-bar"><div class="sr-bar-fill" style="width:${n/maxQ*100}%"></div></div>
    <span class="sr-count">${n}</span></div>`
  ).join("") || '<div style="color:var(--text-muted);font-size:13px">Pas encore de données</div>';

  // Top secteurs
  const secFreq = {};
  entries.forEach(e=>{if(e.sector)secFreq[e.sector]=(secFreq[e.sector]||0)+1;});
  const topSec = Object.entries(secFreq).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const maxSec = topSec[0]?.[1]||1;
  document.getElementById("stats-sectors").innerHTML = topSec.map(([s,n])=>
    `<div class="stats-row"><span class="sr-label">${esc(s.split(" / ")[0])}</span>
    <div class="sr-bar"><div class="sr-bar-fill" style="width:${n/maxSec*100}%"></div></div>
    <span class="sr-count">${n}</span></div>`
  ).join("") || '<div style="color:var(--text-muted);font-size:13px">Filtrez par secteur pour alimenter ces stats</div>';

  // Top médias
  const medFreq = {};
  entries.forEach(e=>{if(e.media)medFreq[e.media]=(medFreq[e.media]||0)+1;});
  const topMed = Object.entries(medFreq).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const maxMed = topMed[0]?.[1]||1;
  document.getElementById("stats-medias").innerHTML = topMed.map(([m,n])=>
    `<div class="stats-row"><span class="sr-label">${esc(m)}</span>
    <div class="sr-bar"><div class="sr-bar-fill" style="width:${n/maxMed*100}%"></div></div>
    <span class="sr-count">${n}</span></div>`
  ).join("") || '<div style="color:var(--text-muted);font-size:13px">Filtrez par média pour alimenter ces stats</div>';
}

document.getElementById("stats-btn").addEventListener("click",()=>{
  renderStats();
  document.getElementById("stats-overlay").classList.add("show");
});
