/* ── NAVIGATION INTER-APPS ──
   Le radar est servi sous /radar par server/index.js, à côté du dashboard (/)
   et du planning (/planning). Même origine, donc la session (localStorage
   commercialId / sessionStorage om_cred) est déjà partagée : passer d'un onglet
   à l'autre ne redemande jamais de se connecter. */
function goApp(path){ window.location.href = path; }

/* ── THÈME ──
   Clé localStorage 'theme' avec 'light' par défaut : EXACTEMENT le même contrat
   que client/src/App.js et planning/frontend/index.html. C'est ce qui fait
   qu'un basculement sombre/clair dans un onglet suit le commercial dans les
   deux autres. Ne pas changer la clé ni le défaut sans les changer partout. */
const th=document.getElementById("theme");
function setTheme(mode){
  document.documentElement.setAttribute("data-theme", mode === "dark" ? "dark" : "light");
  th.textContent = mode === "light" ? "☀ Clair" : "☾ Sombre";
  localStorage.setItem("theme", mode);
}
let mode = localStorage.getItem("theme") || "light";
setTheme(mode);
th.addEventListener("click",()=>{ mode = mode === "dark" ? "light" : "dark"; setTheme(mode); });

/* ── VISIBILITÉ SELON LE RÔLE ──
   Le radar est ouvert à tous les rôles (commercial, édito, communication), donc
   aucun gardien ici. On ajuste seulement la barre de navigation :
     - Paramètres n'apparaît que pour les comptes admin ;
     - l'onglet Dashboard est masqué pour édito et communication non-admin, qui
       n'y ont pas accès côté serveur et y seraient de toute façon redirigés
       (même règle que planning/frontend/index.html).
   En l'absence de session, on ne masque rien : le radar reste utilisable. */
async function applyRoleVisibility(){
  const id = localStorage.getItem("commercialId");
  if(!id) return;
  try{
    // chemin absolu : en relatif, on viserait /radar/api/... qui n'existe pas
    const res = await fetch("/api/auth/me", { headers:{ "x-commercial-id": id } });
    if(!res.ok) return;
    const me = await res.json();
    if(me.isAdmin){
      document.querySelectorAll(".admin-only").forEach(el=>{ el.style.display = ""; });
    }
    const noDashboard = ["edito","communication"].includes(me.accountRole) && !me.isAdmin;
    if(noDashboard){
      const tab = document.querySelector('.app-switch-btn[onclick="goApp(\'/\')"]');
      if(tab) tab.style.display = "none";
    }
  } catch(_){ /* hors ligne ou session invalide : navigation complète par défaut */ }
}
applyRoleVisibility();

